Hit the same problem, is anyone working on the above [plan](https://github.com/pytorch/pytorch/issues/117662#issuecomment-3791173360)?

Repro where this can cause silent incorrectness.
```python
import torch
import torch.utils._pytree as pytree


class Sub(torch.Tensor):
    @staticmethod
    def __new__(cls, data):
        return torch.Tensor._make_wrapper_subclass(
            cls, data.shape, dtype=torch.float32, device=data.device, requires_grad=False)

    def __init__(self, data):
        self._data = data

    def __tensor_flatten__(self):
        return ["_data"], {}

    @staticmethod
    def __tensor_unflatten__(inner, meta, size, stride):
        return Sub(inner["_data"])

    @classmethod
    def __torch_dispatch__(cls, func, types, args, kwargs=None):
        args = pytree.tree_map_only(Sub, lambda t: t._data, args)
        kwargs = pytree.tree_map_only(Sub, lambda t: t._data, kwargs or {})
        return func(*args, **kwargs)


class F(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        return Sub(x * 2)

    @staticmethod
    def backward(ctx, grad_output):
        scale = 100.0 if isinstance(grad_output, Sub) else 1.0
        return grad_output * scale * 2


def model(x):
    out = F.apply(x)          # Sub: subclass intermediate (not a graph output)
    return (out * 1.0).sum()  # consumed by a dense op -> real cotangent is dense


def grad_of(fn, x):
    x = x.clone().detach().requires_grad_(True)
    fn(x).backward()
    return x.grad


x = torch.randn(8)
eager = grad_of(model, x)
torch._dynamo.reset()
compiled = grad_of(torch.compile(model, fullgraph=True), x)

print("eager   :", eager.sum().item())
print("compiled:", compiled.sum().item())
print("ratio   :", (compiled.sum() / eager.sum()).item(), "(should be 1.0)")
```

